sp_widget.client_script:
api.controller = function($scope, $sce, $timeout) {

    var c = this;

    c.isOpen = false;
    c.isFullWindow = false;
    c.isMenuOpen = false;
    c.prompt = '';
    c.messages = []; // ALWAYS start empty on page load/refresh
    c.loading = false;
    c.error = '';

    /*
     * DYNAMIC ROLE RESOLUTION
     */
    function getUserRole() {
        var href = (window.location.href || '').toLowerCase();
        if (href.indexOf('tpo') !== -1) return 'tpo';
        if (href.indexOf('trainer') !== -1) return 'trainer';
        if (href.indexOf('student') !== -1) return 'student';
        return 'student';
    }

    c.userRole = getUserRole();

    function generateConversationId() {
        return 'portal_' + c.userRole + '_' + new Date().getTime() + '_' + Math.floor(Math.random() * 100000);
    }

    c.conversationId = generateConversationId();

    function escapeHtml(value) {
        return String(value || '')
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#39;');
    }

    function renderMarkdown(value) {
        if (!value) return '';
        var text = String(value);

        // Code blocks
        text = text.replace(/```([\s\S]*?)```/g, function(match, code) {
            return '<pre class="campus360-code-block"><code>' + escapeHtml(code.trim()) + '</code></pre>';
        });

        // Headers
        text = text.replace(/^### (.*$)/gim, '<h4 class="ai-h3">$1</h4>');
        text = text.replace(/^## (.*$)/gim, '<h3 class="ai-h2">$1</h3>');
        text = text.replace(/^# (.*$)/gim, '<h2 class="ai-h1">$1</h2>');

        // Bold
        text = text.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

        // Inline code
        text = text.replace(/`([^`]+)`/g, '<code class="ai-inline-code">$1</code>');

        // Italic
        text = text.replace(/(^|[^*])\*(.*?)\*(?!\*)/g, '$1<em>$2</em>');

        // Bullet points
        text = text.replace(/^\s*[-*]\s+(.*)$/gim, '<li>$1</li>');
        text = text.replace(/(<li>[\s\S]*?<\/li>)/g, '<ul class="ai-list">$1</ul>');
        text = text.replace(/<\/ul>\s*<ul>/g, '');

        // Paragraph line breaks
        text = text.replace(/\n\n/g, '<br><br>');
        text = text.replace(/\n/g, '<br>');

        return text;
    }

    c.trustHtml = function(text) {
        return $sce.trustAsHtml(renderMarkdown(text));
    };

    c.scrollToBottom = function() {
        $timeout(function() {
            var el = document.getElementById('campus360-ai-chat-body');
            if (el) el.scrollTop = el.scrollHeight;
        }, 100);
    };

    c.openAssistant = function() {
        c.isOpen = true;
        c.isMenuOpen = false;
        c.error = '';
        c.scrollToBottom();
    };

    c.closeAssistant = function() {
        c.isOpen = false;
        c.isMenuOpen = false;
        c.error = '';
    };

    c.openFullWindow = function() {
        c.isOpen = true;
        c.isFullWindow = true;
        c.isMenuOpen = false;
        c.error = '';
        c.scrollToBottom();
    };

    c.closeFullWindow = function() {
        c.isFullWindow = false;
        c.isMenuOpen = false;
        c.scrollToBottom();
    };

    c.toggleMenu = function() {
        c.isMenuOpen = !c.isMenuOpen;
    };

    c.useSuggestion = function(question) {
        c.prompt = question;
        c.sendMessage();
    };

    c.clearChat = function() {
        c.messages = [];
        c.error = '';
        c.conversationId = generateConversationId();
    };

    c.handleKeyDown = function(e) {
        if (e.keyCode === 13 && !e.shiftKey) {
            e.preventDefault();
            c.sendMessage();
        }
    };

    c.sendMessage = function() {
        if (!c.prompt || !c.prompt.trim() || c.loading) return;

        var userPrompt = c.prompt.trim();
        c.error = '';

        c.messages.push({
            role: 'user',
            content: userPrompt,
            displayContent: escapeHtml(userPrompt)
        });

        c.prompt = '';
        c.loading = true;
        c.scrollToBottom();

        c.server.get({
            action: 'ask',
            prompt: userPrompt,
            role: c.userRole,
            conversationId: c.conversationId
        }).then(function(response) {
            c.loading = false;
            if (response.data && response.data.response) {
                var assistantContent = String(response.data.response);
                c.messages.push({
                    role: 'assistant',
                    content: assistantContent,
                    displayContent: $sce.trustAsHtml(renderMarkdown(assistantContent))
                });
            } else if (response.data && response.data.error) {
                c.error = response.data.error;
            } else {
                c.error = 'Campus360 AI returned an empty response.';
            }
            c.scrollToBottom();
        }, function(error) {
            c.loading = false;
            c.error = 'Unable to contact Campus360 AI. Please try again.';
            c.scrollToBottom();
        });
    };

};

sp_widget.css:
/* =========================================================
   ROOT & FLOATING LAUNCHER
   ========================================================= */

.campus360-ai {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif !important;
    position: fixed !important;
    right: 28px !important;
    bottom: 28px !important;
    z-index: 999999 !important;
}

.campus360-ai-launcher {
    position: fixed !important;
    right: 28px !important;
    bottom: 28px !important;
    width: 60px !important;
    height: 60px !important;
    border: none !important;
    border-radius: 50% !important;
    background: linear-gradient(135deg, #172554 0%, #3b82f6 100%) !important;
    color: #ffffff !important;
    box-shadow: 0 10px 30px rgba(15, 23, 42, 0.4) !important;
    cursor: pointer !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    z-index: 999999 !important;
    transition: transform 0.2s ease, box-shadow 0.2s ease !important;
}

.campus360-ai-launcher:hover {
    transform: scale(1.08) translateY(-2px) !important;
    box-shadow: 0 14px 35px rgba(15, 23, 42, 0.5) !important;
}

.launcher-icon {
    font-size: 26px !important;
    line-height: 1 !important;
}

/* =========================================================
   FLOATING PANEL
   ========================================================= */

.campus360-ai-panel {
    position: fixed !important;
    right: 28px !important;
    bottom: 28px !important;
    width: 400px !important;
    max-width: calc(100vw - 40px) !important;
    height: 610px !important;
    max-height: calc(100vh - 50px) !important;
    background: #ffffff !important;
    border-radius: 18px !important;
    overflow: hidden !important;
    box-shadow: 0 24px 70px rgba(15, 23, 42, 0.35) !important;
    display: flex !important;
    flex-direction: column !important;
    z-index: 999999 !important;
}

.campus360-ai-header {
    position: relative !important;
    min-height: 72px !important;
    padding: 14px 16px !important;
    background: #172554 !important;
    color: #ffffff !important;
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
}

.campus360-ai-brand {
    display: flex !important;
    align-items: center !important;
    gap: 11px !important;
}

.campus360-ai-avatar {
    width: 40px !important;
