    height: 38px !important;
    border: none !important;
    border-radius: 10px !important;
    background: #172554 !important;
    color: #ffffff !important;
    cursor: pointer !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    font-size: 14px !important;
}

.campus360-ai-send[disabled] {
    opacity: 0.4 !important;
    cursor: not-allowed !important;
}

/* Full Window Overrides */
.campus360-ai-full-window-shell {
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    background: #ffffff !important;
    z-index: 1000000 !important;
    display: flex !important;
}

sp_widget.script:
(function() {

    data.response = '';
    data.error = '';

    if (!input) return;

    if (input.action === 'clear') {
        data.response = 'Chat cleared successfully.';
        return;
    }

    if (input.action !== 'ask') return;

    var prompt = String(input.prompt || '').trim();
    var conversationId = String(input.conversationId || '').trim();

    if (!prompt) {
        data.error = 'Please enter a question.';
        return;
    }

    /*
     * ============================================================
     * USER ROLE & IDENTITY RESOLUTION
     * ============================================================
     */
    var userRole = 'student'; // 'student', 'tpo', 'trainer'
    var requestedRole = ($sp.getParameter('role') || input.role || '').toLowerCase();
    var pageId = ($sp.getParameter('id') || '').toLowerCase();

    if (requestedRole === 'tpo' || pageId.indexOf('tpo') !== -1) {
        userRole = 'tpo';
    } else if (requestedRole === 'trainer' || pageId.indexOf('trainer') !== -1) {
        userRole = 'trainer';
    }

    // Resolve Student Record (Prioritize URL parameter 'student' e.g. STU_TEST_001)
    var studentSysId = '';
    var studentName = 'Test Student Campus360';
    var studentId = 'STU_TEST_001';

    var reqStudent = $sp.getParameter('student') || input.student || 'STU_TEST_001';
    var stuGR = new GlideRecord('x_snc_campus360_student_master');

    if (reqStudent) {
        stuGR.addQuery('student_id', reqStudent);
        stuGR.query();
        if (stuGR.next()) {
            studentSysId = stuGR.getUniqueValue();
            studentName = stuGR.getValue('student_name') || 'Student';
            studentId = stuGR.getValue('student_id') || reqStudent;
        } else {
            stuGR = new GlideRecord('x_snc_campus360_student_master');
            if (stuGR.get(reqStudent)) {
                studentSysId = stuGR.getUniqueValue();
                studentName = stuGR.getValue('student_name') || 'Student';
                studentId = stuGR.getValue('student_id') || reqStudent;
            }
        }
    }

    if (!studentSysId) {
        stuGR = new GlideRecord('x_snc_campus360_student_master');
        stuGR.addQuery('student_id', 'STU_TEST_001');
        stuGR.query();
        if (stuGR.next()) {
            studentSysId = stuGR.getUniqueValue();
            studentName = stuGR.getValue('student_name') || 'Test Student Campus360';
            studentId = 'STU_TEST_001';
        }
    }

    // Resolve Trainer Record (Prioritize URL parameter 'trainer' e.g. TR001)
    var trainerSysId = '';
    var trainerName = 'Dr. Anil Varma';
    var reqTrainer = $sp.getParameter('trainer') || input.trainer || 'TR001';
    var trGR = new GlideRecord('x_snc_campus360_trainer_master');

    if (reqTrainer) {
        trGR.addQuery('trainer_id', reqTrainer);
        trGR.query();
        if (trGR.next()) {
            trainerSysId = trGR.getUniqueValue();
            trainerName = trGR.getValue('trainer_name') || 'Trainer';
        } else {
            trGR = new GlideRecord('x_snc_campus360_trainer_master');
            if (trGR.get(reqTrainer)) {
                trainerSysId = trGR.getUniqueValue();
                trainerName = trGR.getValue('trainer_name') || 'Trainer';
            }
        }
    }

    if (!trainerSysId) {
        trGR = new GlideRecord('x_snc_campus360_trainer_master');
        trGR.addQuery('trainer_id', 'TR001');
        trGR.query();
        if (trGR.next()) {
            trainerSysId = trGR.getUniqueValue();
            trainerName = trGR.getValue('trainer_name') || 'Dr. Anil Varma';
        }
    }

    var lowerPrompt = prompt.toLowerCase();
    var responseMessage = '';

    /*
     * ============================================================
     * 1. CGPA FILTERING QUERY (TPO / TRAINER / ALL ROLES)
     * e.g. "students who have cgpa greater than 8", "cgpa with 8", "cgpa > 7.5"
     * ============================================================
     */
    if (lowerPrompt.indexOf('cgpa') !== -1 || lowerPrompt.indexOf('gpa') !== -1) {

        var minCgpa = 8.0;
        var cgpaMatch = lowerPrompt.match(/(?:greater than|above|with|>=|>|higher than|\s)(\d+(?:\.\d+)?)/);
        if (cgpaMatch && cgpaMatch[1]) {
            minCgpa = parseFloat(cgpaMatch[1]);
        }

        var allStudentGR = new GlideRecord('x_snc_campus360_student_master');
        allStudentGR.query();

        var matchedStudents = [];
        while (allStudentGR.next()) {
            var valStr = allStudentGR.getValue('cgpa') || allStudentGR.getValue('gpa') || '0';
            var valNum = parseFloat(valStr);
            if (valNum >= minCgpa) {
                matchedStudents.push({
                    name: allStudentGR.getValue('student_name') || 'Student Candidate',
                    id: allStudentGR.getValue('student_id') || 'N/A',
                    cgpa: valStr,
                    cgpaNum: valNum,
                    branch: (allStudentGR.getValue('branch') || allStudentGR.getValue('department') || 'CSE').toUpperCase(),
                    email: allStudentGR.getValue('email') || ''
                });
            }
        }

        matchedStudents.sort(function(a, b) { return b.cgpaNum - a.cgpaNum; });

        var cgpaList = [];
        for (var cIdx = 0; cIdx < matchedStudents.length && cIdx < 15; cIdx++) {
            var stItem = matchedStudents[cIdx];
            cgpaList.push((cIdx + 1) + '. **' + stItem.name + '** (`' + stItem.id + '`) - CGPA: **' + stItem.cgpa + '** | Branch: `' + stItem.branch + '`');
        }

        responseMessage = '### 🎓 Student List with CGPA ≥ ' + minCgpa.toFixed(1) + ' (' + matchedStudents.length + ' Students Found)\n\n' +
            'Here are the top performing student profiles in Campus360:\n\n' +
            (cgpaList.length > 0 ? cgpaList.join('\n') : 'No student records found with CGPA ≥ ' + minCgpa.toFixed(1) + '.');
    }

    /*
     * ============================================================
     * 2. SPECIFIC OPPORTUNITY APPLICANTS QUERY (TPO / ALL ROLES)
     * e.g. "Tell me how many students applied for Data analyst intern opportunity"
     * ============================================================
     */
    else if (lowerPrompt.indexOf('applied') !== -1 || lowerPrompt.indexOf('applicant') !== -1 || (lowerPrompt.indexOf('students') !== -1 && lowerPrompt.indexOf('opportunit') !== -1)) {

        var targetOppGR = new GlideRecord('x_snc_campus360_placement_opportunity');
        targetOppGR.orderByDesc('sys_created_on');
        targetOppGR.query();

        var matchedOpp = null;
        var oppStopWords = ['tell','me','how','many','students','student','applied','for','the','a','an','opportunity','drive','placement','company','job','role','internship','please','show','count','what','list','which','who'];
        var oppTokens = lowerPrompt.split(/\s+/).filter(function(t) {
            return t.length > 2 && oppStopWords.indexOf(t) === -1;
        });

        while (targetOppGR.next()) {
            var title = (targetOppGR.getValue('opportunity_title') || targetOppGR.getValue('title') || targetOppGR.getValue('job_role') || '').toLowerCase();
            var oppNum = (targetOppGR.getValue('opportunity_id') || targetOppGR.getValue('number') || '').toLowerCase();
            var compName = (targetOppGR.getDisplayValue('company') || '').toLowerCase();

            var matchFound = false;
            for (var k = 0; k < oppTokens.length; k++) {
                if (title.indexOf(oppTokens[k]) !== -1 || oppNum.indexOf(oppTokens[k]) !== -1 || compName.indexOf(oppTokens[k]) !== -1) {
                    matchFound = true;
                    break;
                }
            }

            if (matchFound) {
                matchedOpp = {
                    sys_id: targetOppGR.getUniqueValue(),
                    title: targetOppGR.getValue('opportunity_title') || targetOppGR.getValue('title') || targetOppGR.getValue('job_role') || 'Placement Drive',
                    oppId: targetOppGR.getValue('opportunity_id') || 'OPP',
                    company: targetOppGR.getDisplayValue('company') || 'Partner Recruiter'
                };
                break;
            }
        }

        if (matchedOpp) {
            var appCountGR = new GlideRecord('x_snc_campus360_student_application');
            appCountGR.addQuery('opportunity', matchedOpp.sys_id);
            appCountGR.query();

            var totalApplicants = appCountGR.getRowCount();
            var applicantList = [];

            while (appCountGR.next()) {
                var sSysId = appCountGR.getValue('student');
                var sName = appCountGR.getDisplayValue('student') || 'Student Candidate';
                var sCgpa = '';

                var sMasterGR = new GlideRecord('x_snc_campus360_student_master');
                if (sMasterGR.get(sSysId)) {
                    sName = sMasterGR.getValue('student_name') || sName;
                    sCgpa = sMasterGR.getValue('cgpa') ? ' | CGPA: ' + sMasterGR.getValue('cgpa') : '';
                }

                var status = appCountGR.getDisplayValue('status') || 'Applied';
                applicantList.push('- **' + sName + '** (' + status + sCgpa + ')');
            }

            responseMessage = '### 📄 Application Details for "' + matchedOpp.title + '" (' + matchedOpp.company + ')\n\n' +
                '**Opportunity ID:** `' + matchedOpp.oppId + '` | **Total Enrolled Applicants:** **' + totalApplicants + ' Students**\n\n' +
                (applicantList.length > 0 ? '**Applicant Students List:**\n' + applicantList.join('\n') : 'No students have applied for this drive yet.');
        } else {
            var allOppGR = new GlideRecord('x_snc_campus360_placement_opportunity');
            allOppGR.setLimit(10);
            allOppGR.query();

            var driveSummary = [];
            while (allOppGR.next()) {
                var driveSysId = allOppGR.getUniqueValue();
                var driveTitle = allOppGR.getValue('opportunity_title') || allOppGR.getValue('title') || 'Placement Drive';
                var driveComp = allOppGR.getDisplayValue('company') || 'Partner Recruiter';

                var driveAppGR = new GlideRecord('x_snc_campus360_student_application');
                driveAppGR.addQuery('opportunity', driveSysId);
                driveAppGR.query();

                driveSummary.push('- **' + driveTitle + '** (' + driveComp + '): **' + driveAppGR.getRowCount() + ' applicants**');
            }

            responseMessage = '### 📄 Placement Opportunities Applicant Breakdown\n\n' +
                'Here is the applicant count breakdown for placement drives:\n\n' +
                driveSummary.join('\n');
        }
    }

    /*
     * ============================================================
     * 3. STUDENT READINESS & SKILL GAP QUERY
     * e.g. "my skill gap", "readiness", "how ready am i"
     * ============================================================
     */
    else if (userRole === 'student' && (lowerPrompt.indexOf('skill gap') !== -1 || lowerPrompt.indexOf('readiness') !== -1 || lowerPrompt.indexOf('ready') !== -1 || lowerPrompt.indexOf('intelligence') !== -1)) {

        var intelGR = new GlideRecord('x_snc_campus360_placement_intelligence');
        intelGR.addQuery('student', studentSysId);
        intelGR.query();

        if (intelGR.next()) {
            var score = intelGR.getValue('readiness_score') || '75';
            var skillGap = intelGR.getValue('primary_skill_gap') || 'Communication';
            var bottleneck = intelGR.getValue('bottleneck_stage') || 'Interviews';
            var risk = intelGR.getValue('risk_level') || 'Medium';
            var partScore = intelGR.getValue('participation_score') || '85';
            var missedOpp = intelGR.getValue('missed_opportunities') || '1';
            var summaryText = intelGR.getValue('skill_gap_summary') || 'Communication needs improvement.';
            var actionText = intelGR.getValue('recommended_action') || 'Engage in targeted communication skills training.';

            responseMessage = '### 📊 Your Placement Readiness & Skill Intelligence\n\n' +
                '**Student:** ' + studentName + ' (`' + studentId + '`)\n' +
                '- **Overall Readiness Score:** **' + score + ' / 100** (Risk Level: `' + risk + '`)\n' +
                '- **Primary Skill Gap:** **' + skillGap + '**\n' +
                '- **Bottleneck Stage:** **' + bottleneck + '**\n' +
                '- **Participation Score:** **' + partScore + ' / 100**\n' +
                '- **Missed Opportunities:** **' + missedOpp + '**\n\n' +
                '**Skill Gap Summary:**\n' + summaryText + '\n\n' +
                '**Recommended Action:**\n' + actionText;
        } else {
            responseMessage = '### 📊 Placement Readiness Summary\n\n' +
                '**Student:** ' + studentName + ' (`' + studentId + '`)\n' +
                '- **Overall Readiness Score:** **75 / 100** (Risk Level: `Medium`)\n' +
                '- **Primary Skill Gap:** **Communication**\n' +
                '- **Bottleneck Stage:** **Interviews**';
        }
    }

    /*
     * ============================================================
     * 4. MOCK INTERVIEWS QUERY (STUDENT & TRAINER & TPO)
     * e.g. "how many mock interviews i requested for"
     * ============================================================
     */
    else if (lowerPrompt.indexOf('mock') !== -1 || lowerPrompt.indexOf('requested') !== -1 || lowerPrompt.indexOf('slot') !== -1) {

        var mockGR = new GlideRecord('x_snc_campus360_mock_interview');
        if (userRole === 'student' && studentSysId) {
            mockGR.addQuery('student', studentSysId);
        } else if (userRole === 'trainer' && trainerSysId) {
            mockGR.addQuery('trainer', trainerSysId);
        }
        mockGR.query();

        var totalMocks = mockGR.getRowCount();
        var mockList = [];
        var count = 0;

        while (mockGR.next() && count < 8) {
            var trName = mockGR.getDisplayValue('trainer') || 'Assigned Trainer';
            var stName = mockGR.getDisplayValue('student') || 'Student';
            var topic = mockGR.getValue('topic') || mockGR.getValue('interview_type') || 'Technical Practice';
            var sDate = mockGR.getDisplayValue('scheduled_date') || mockGR.getDisplayValue('sys_created_on') || 'Scheduled';
            var status = mockGR.getDisplayValue('status') || 'Pending';

            if (userRole === 'student') {
                mockList.push('- **Topic: ' + topic + '** with Trainer **' + trName + '** (Scheduled: ' + sDate + ' | Status: `' + status + '`)');
            } else {
                mockList.push('- Student: **' + stName + '** - Topic: *' + topic + '* (Scheduled: ' + sDate + ' | Status: `' + status + '`)');
            }
            count++;
        }

        responseMessage = '### 🗓️ Mock Interview Requests (' + totalMocks + ' Total Sessions)\n\n' +
            'There are **' + totalMocks + ' practice session(s)** recorded:\n\n' +
            (mockList.length > 0 ? mockList.join('\n') : '0 mock interview requests found.');
    }

    /*
     * ============================================================
     * 5. PROGRAM ENROLLMENT QUERY (TPO / TRAINER / ALL ROLES)
     * e.g. "Can tell me students enrolled in Problem solving training program"
     * ============================================================
     */
    else if (lowerPrompt.indexOf('enrolled') !== -1 || lowerPrompt.indexOf('enrollment') !== -1 || (lowerPrompt.indexOf('students') !== -1 && lowerPrompt.indexOf('program') !== -1)) {

        var progGR = new GlideRecord('x_snc_campus360_training_program');
        progGR.query();

        var matchedProg = null;
        var stopWords = ['can','tell','me','students','student','are','enrolled','enrollment','in','the','a','an','training','program','course','batch','please','show','count','what','which','who'];
        var tokens = lowerPrompt.split(/\s+/).filter(function(t) {
            return t.length > 2 && stopWords.indexOf(t) === -1;
        });

        while (progGR.next()) {
            var pName = (progGR.getValue('training_name') || progGR.getValue('name') || '').toLowerCase();
            var pSkill = (progGR.getValue('skill_area') || '').toLowerCase();
            var pCode = (progGR.getValue('training_id') || '').toLowerCase();

            var matchFound = false;
            for (var k = 0; k < tokens.length; k++) {
                if (pName.indexOf(tokens[k]) !== -1 || pSkill.indexOf(tokens[k]) !== -1 || pCode.indexOf(tokens[k]) !== -1) {
                    matchFound = true;
                    break;
                }
            }

            if (matchFound) {
                matchedProg = {
                    sys_id: progGR.getUniqueValue(),
                    title: progGR.getValue('training_name') || progGR.getValue('name') || 'Training Program',
                    skill: progGR.getValue('skill_area') || 'General',
                    trainer: progGR.getDisplayValue('trainer') || 'Assigned Trainer'
                };
                break;
            }
        }

        if (matchedProg) {
            var enrollGR = new GlideRecord('x_snc_campus360_training_enrollment');
            enrollGR.addQuery('training_program', matchedProg.sys_id);
            enrollGR.query();

            var studentList = [];
            while (enrollGR.next()) {
                var sSysId = enrollGR.getValue('student');
                var sDisplay = enrollGR.getDisplayValue('student') || 'Enrolled Student';

                var sMasterGR = new GlideRecord('x_snc_campus360_student_master');
                if (sMasterGR.get(sSysId)) {
                    sDisplay = sMasterGR.getValue('student_name') || sDisplay;
                }
                studentList.push('- **' + sDisplay + '**');
            }

            responseMessage = '### 🎓 Enrollment Details: "' + matchedProg.title + '"\n\n' +
                '**Skill Domain:** ' + matchedProg.skill + ' | **Trainer:** ' + matchedProg.trainer + '\n\n' +
                '**Total Enrolled Students:** **' + enrollGR.getRowCount() + ' Students**\n\n' +
                (studentList.length > 0 ? '**Enrolled Student Roster:**\n' + studentList.join('\n') : 'No students are currently enrolled in this training program.');
        } else {
            var allProgGR = new GlideRecord('x_snc_campus360_training_program');
            allProgGR.setLimit(10);
            allProgGR.query();

            var progSummary = [];
            while (allProgGR.next()) {
                var pSysId = allProgGR.getUniqueValue();
                var pTitle = allProgGR.getValue('training_name') || allProgGR.getValue('name') || 'Training Program';

                var pEnrollGR = new GlideRecord('x_snc_campus360_training_enrollment');
                pEnrollGR.addQuery('training_program', pSysId);
                pEnrollGR.query();

                progSummary.push('- **' + pTitle + '**: **' + pEnrollGR.getRowCount() + ' enrolled students**');
            }

            responseMessage = '### 🎓 Campus360 Training Programs Enrollment Overview\n\n' +
                'Here is the enrollment count for active training programs:\n\n' +
                progSummary.join('\n');
        }
    }

    /*
     * ============================================================
     * 6. TOP 2 / RECENTLY PUBLISHED OPPORTUNITIES
     * ============================================================
     */
    else if (lowerPrompt.indexOf('top 2') !== -1 || lowerPrompt.indexOf('top two') !== -1 || (lowerPrompt.indexOf('recent') !== -1 && lowerPrompt.indexOf('opportunit') !== -1)) {
        var topOppGR = new GlideRecord('x_snc_campus360_placement_opportunity');
        topOppGR.orderByDesc('sys_created_on');
        topOppGR.setLimit(2);
        topOppGR.query();

        var topOppList = [];
        var idx = 1;

        while (topOppGR.next()) {
            var cName = topOppGR.getDisplayValue('company') || 'Partner Recruiter';
            var role = topOppGR.getValue('opportunity_title') || topOppGR.getValue('title') || topOppGR.getValue('job_role') || 'Placement Drive';
            var ctc = topOppGR.getValue('ctc_stipend') || topOppGR.getValue('ctc_package') || 'As per norms';
            var deadline = topOppGR.getDisplayValue('application_deadline') || topOppGR.getDisplayValue('deadline') || 'Open';
            topOppList.push(idx + '. **' + role + '** at **' + cName + '**\n   - **Package:** ' + ctc + '\n   - **Deadline:** ' + deadline);
            idx++;
        }

        if (topOppList.length > 0) {
            responseMessage = '### 💼 Top 2 Recently Published Opportunities\n\n' + topOppList.join('\n\n');
        } else {
            responseMessage = 'No published placement opportunities were found in Campus360.';
        }
    }

    /*
     * ============================================================
     * 7. GENERAL PLACEMENT OPPORTUNITIES
     * ============================================================
     */
    else if (lowerPrompt.indexOf('opportunit') !== -1 || lowerPrompt.indexOf('drive') !== -1) {
        var oppGR = new GlideRecord('x_snc_campus360_placement_opportunity');
        oppGR.orderByDesc('sys_created_on');
        oppGR.setLimit(10);
        oppGR.query();

        var oppList = [];
        while (oppGR.next()) {
            var cName = oppGR.getDisplayValue('company') || 'Partner Company';
            var role = oppGR.getValue('opportunity_title') || oppGR.getValue('title') || oppGR.getValue('job_role') || 'Placement Drive';
            var ctc = oppGR.getValue('ctc_stipend') || oppGR.getValue('ctc_package') || 'As per norms';
            var deadline = oppGR.getDisplayValue('application_deadline') || oppGR.getDisplayValue('deadline') || 'Open';
            oppList.push('- **' + role + '** at **' + cName + '** (CTC: ' + ctc + ' | Deadline: ' + deadline + ')');
        }

        responseMessage = '### 💼 Active Campus Placement Opportunities (' + oppGR.getRowCount() + ' Drives)\n\n' +
            oppList.join('\n');
    }

    /*
     * ============================================================
     * 8. GROQ / AI FALLBACK
     * ============================================================
     */
    else {
        try {
            var aiService = new x_snc_campus360.Campus360AIService();
            var rawResult = aiService.processAIMessage(prompt, conversationId);
            var parsedResult = JSON.parse(rawResult);
            responseMessage = parsedResult.response || 'Campus360 AI completed your request.';
        } catch (groqEx) {
            responseMessage = '### ✦ Campus360 AI Assistant\n\nHello **' + (userRole === 'student' ? studentName : (userRole === 'trainer' ? trainerName : 'TPO Administrator')) + '**!\n\nAsk me questions like:\n- *"Tell me how many students applied for Data Analyst Intern opportunity"* \n- *"Tell me list of students who have cgpa greater than 8"* \n- *"Can tell me students enrolled in Problem solving training program?"* \n- *"What are top 2 recently published opportunities?"*';
        }
    }

    data.response = responseMessage;

})();
